#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
ENV_FILE=".env"

banner "stonelasley.com v2: accounts, DNS and tokens"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: add the stonelasley.com zone"
say "Cloudflare will host DNS so R2 can serve images from img.stonelasley.com."
say "Current records at Namecheap, so you can check Cloudflare imported them all:"
note "  A     @    $(dig +short A stonelasley.com | tr '\n' ' ')"
note "  CNAME www  $(dig +short CNAME www.stonelasley.com | tr '\n' ' ')"
note "  MX    @    $(dig +short MX stonelasley.com | tr '\n' ' ')"
note "  TXT   @    $(dig +short TXT stonelasley.com | tr '\n' ' ')"
open_url "https://dash.cloudflare.com/"
step "Sign in (or sign up), then click 'Add a domain' and enter stonelasley.com."
step "Choose the Free plan. Let it scan, then compare its records to the list above."
step "Set the Vercel A and www CNAME records to 'DNS only' (grey cloud), not proxied."
step "Leave the MX/TXT forwarding records for now; stage 2 replaces them."
step "Finish setup, but DON'T change nameservers at Namecheap yet (stage 6)."
step "Write down the two nameservers Cloudflare assigns (e.g. xxx.ns.cloudflare.com)."
step "Open the zone's Overview page; the right sidebar's API section shows both IDs."
ask CLOUDFLARE_ACCOUNT_ID "Paste the Account ID:"
ask CLOUDFLARE_ZONE_ID "Paste the Zone ID:"
ask CLOUDFLARE_NS1 "First Cloudflare nameserver:"
ask CLOUDFLARE_NS2 "Second Cloudflare nameserver:"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
write_env CLOUDFLARE_ZONE_ID "$CLOUDFLARE_ZONE_ID"
write_env CLOUDFLARE_NS1 "$CLOUDFLARE_NS1"
write_env CLOUDFLARE_NS2 "$CLOUDFLARE_NS2"
set_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
set_var CLOUDFLARE_ZONE_ID "$CLOUDFLARE_ZONE_ID"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Email: replace Namecheap forwarding with Cloudflare Email Routing"
say "Mail to @stonelasley.com is forwarded by Namecheap today. That service is"
say "tied to Namecheap's nameservers, so set up the replacement before moving them."
say "First, list the aliases you forward now:"
open_url "https://ap.www.namecheap.com/domains/list/"
step "stonelasley.com → Manage → find the email forwarding / Redirect Email list."
step "Note every alias and the address it forwards to."
pause "Got the list? Press Enter to open Cloudflare Email Routing."
open_url "https://dash.cloudflare.com/${CLOUDFLARE_ACCOUNT_ID}/stonelasley.com/email/routing/overview"
step "Click Get started / Enable Email Routing."
step "Add each destination address and confirm the verification email it sends."
step "Create one custom address per Namecheap alias, pointing at its destination."
step "Let Cloudflare add its MX + SPF records and remove the eforward* ones."
note "These only take effect once the nameservers move in stage 6."
pause "Email Routing set up for every alias? Press Enter."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: enable R2"
say "R2 is free at this size but needs a payment method on file before first use."
open_url "https://dash.cloudflare.com/${CLOUDFLARE_ACCOUNT_ID}/r2/overview"
step "Click through the R2 enable / purchase flow and add a payment method."
step "Don't create any buckets: I'll create them from the CLI."
pause "R2 enabled? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: API token for CI and the CLI"
say "One token for wrangler deploys, D1 migrations and Vectorize index builds."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Custom token → name it 'stonelasley-v2-ci'."
step "Account permissions (all on your account), each set to Edit:"
note "    D1 · Workers R2 Storage · Vectorize · Workers Scripts · Workers AI"
note "    plus Account Settings: Read"
step "Zone permissions, Zone resources = stonelasley.com, each set to Edit:"
note "    Workers Routes · DNS"
note "Exact permission labels may differ slightly; pick the closest match."
step "Continue → Create Token, then copy it (it's shown once)."
ask_secret CLOUDFLARE_API_TOKEN "Paste the API token:"
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
if command -v curl >/dev/null 2>&1; then
  if curl -fsS -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
       https://api.cloudflare.com/client/v4/user/tokens/verify | grep -q '"active"'; then
    printf '  %s✓ token verified active%s\n' "$GREEN" "$RESET"
  else
    warn "token didn't verify; re-run this wizard to paste it again"
  fi
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: Turnstile widget for Access Code exchange"
open_url "https://dash.cloudflare.com/${CLOUDFLARE_ACCOUNT_ID}/turnstile"
step "Add widget → name 'access-code', hostname stonelasley.com, mode Managed."
step "Copy the Site Key and the Secret Key."
note "Preview and local dev use Cloudflare's published test keys, so this is prod only."
ask TURNSTILE_SITE_KEY "Paste the Site Key:"
ask_secret TURNSTILE_SECRET_KEY "Paste the Secret Key:"
write_env TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
write_env TURNSTILE_SECRET_KEY "$TURNSTILE_SECRET_KEY"
set_var TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
set_secret TURNSTILE_SECRET_KEY "$TURNSTILE_SECRET_KEY"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Namecheap: point nameservers at Cloudflare"
warn "This moves live DNS for the site and email. Propagation can take up to 48h."
say "Before you switch, check in Cloudflare that the A, www CNAME and email records"
say "are all present. If DNSSEC is on at Namecheap, turn it off first."
if confirm "Cloudflare records checked and ready to switch nameservers?"; then
  open_url "https://ap.www.namecheap.com/domains/list/"
  step "stonelasley.com → Manage → Nameservers → Custom DNS."
  step "Enter $CLOUDFLARE_NS1 and $CLOUDFLARE_NS2, then click the green check."
  step "Back in Cloudflare, click 'Check nameservers now' on the zone overview."
  pause "Saved at Namecheap? Press Enter."
  note "Current NS: $(dig +short NS stonelasley.com | tr '\n' ' ')"
  note "Cloudflare emails you when the zone goes Active."
else
  SKIPPED+=("Namecheap nameserver switch to $CLOUDFLARE_NS1 / $CLOUDFLARE_NS2")
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Azure: pick your personal subscription"
warn "Your az CLI defaults to FreshByte's subscription. The site must not go there."
PREV_AZ_SUB=$(az account show --query id -o tsv 2>/dev/null || true)
say "Subscriptions visible to az right now:"
az account list --query "[].{name:name, id:id}" -o table 2>/dev/null | sed 's/^/    /' || true
say "If your personal subscription isn't listed, I'll run 'az login' so you can"
say "sign in with your personal Microsoft account. Your current default is restored after."
if confirm "Personal subscription missing from the list above?"; then
  az login --only-show-errors >/dev/null || warn "az login failed; re-run this stage"
  az account list --query "[].{name:name, id:id}" -o table 2>/dev/null | sed 's/^/    /' || true
fi
note "No personal subscription at all? Create a pay-as-you-go one at"
note "https://portal.azure.com/#view/Microsoft_Azure_Billing/SubscriptionsBlade, then re-run."
while :; do
  ask AZURE_SUBSCRIPTION_ID "Paste your personal subscription ID:"
  AZ_SUB_NAME=$(az account show --subscription "$AZURE_SUBSCRIPTION_ID" --query name -o tsv 2>/dev/null || true)
  if [[ -z "$AZ_SUB_NAME" ]]; then warn "az can't see that subscription; check the ID"; continue; fi
  if [[ "$AZ_SUB_NAME" =~ FB|[Ff]resh ]]; then warn "'$AZ_SUB_NAME' looks like FreshByte's; pick your personal one"; continue; fi
  confirm "Use '$AZ_SUB_NAME' for stonelasley.com?" && break
done
AZURE_TENANT_ID=$(az account show --subscription "$AZURE_SUBSCRIPTION_ID" --query tenantId -o tsv)
[[ -n "$PREV_AZ_SUB" ]] && az account set --subscription "$PREV_AZ_SUB" >/dev/null 2>&1 || true
note "az default left on: $(az account show --query name -o tsv 2>/dev/null || echo unknown)"
write_env AZURE_SUBSCRIPTION_ID "$AZURE_SUBSCRIPTION_ID"
write_env AZURE_TENANT_ID "$AZURE_TENANT_ID"
set_secret AZURE_SUBSCRIPTION_ID "$AZURE_SUBSCRIPTION_ID"
set_secret AZURE_TENANT_ID "$AZURE_TENANT_ID"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Vercel: token and project IDs for CLI deploys"
say "The deploy workflow runs 'vercel deploy' itself after the API is healthy."
open_url "https://vercel.com/account/settings/tokens"
step "Create a token named 'stonelasley-v2-ci', scoped to your personal account."
ask_secret VERCEL_TOKEN "Paste the token:"
open_url "https://vercel.com/account/settings"
step "General → copy your Vercel ID (this is the org ID for a personal account)."
ask VERCEL_ORG_ID "Paste the Vercel ID:"
step "Open the stonelasley.com project → Settings → General → copy the Project ID."
ask VERCEL_PROJECT_ID "Paste the Project ID:"
note "Don't turn off Git auto-deploy yet: that happens when the new deploy workflow lands."
write_env VERCEL_TOKEN "$VERCEL_TOKEN"
write_env VERCEL_ORG_ID "$VERCEL_ORG_ID"
write_env VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"
set_secret VERCEL_TOKEN "$VERCEL_TOKEN"
set_secret VERCEL_ORG_ID "$VERCEL_ORG_ID"
set_secret VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"

finish
say "Next: tell Claude the wizard is done. It creates D1, R2, Vectorize, the Azure"
say "resource group, Container Apps environments, the OIDC app and the content repo."
printf '\n'
}

run_wizard "$@"; exit
